mapper.select:
SELECT DATE_FORMAT(create_time, '%m') AS time, COUNT(*) AS createCount, SUM(CASE WHEN status = '3' THEN 1 ELSE 0 END) AS finishCount FROM inspect_plan
AND create_time BETWEEN #{timeRange[0]} AND #{timeRange[1]}
GROUP BY DATE_FORMAT(create_time, '%m') ORDER BY time

SELECT type AS typeName, COUNT(*) AS count FROM inspect_plan
AND create_time BETWEEN #{timeRange[0]} AND #{timeRange[1]}
GROUP BY type ORDER BY count DESC
